// Answers 200 when the control plane can reach a cluster and 503 when it cannot, which is the difference between "running" and "working".
//
// Returns a wrapper object for the known response body format(s).
//
// Corresponds with GET /readyz (the `Ready` operationId).
func (c *ClientWithResponses) ReadyWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*ReadyResponse, error) {
	rsp, err := c.Ready(ctx, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseReadyResponse(rsp)
}

// ProxyToSandboxWithResponse Proxy to a sandbox's own port
//
// The data plane: everything under this prefix is forwarded to the sandbox's container. What comes back is whatever the sandbox serves — HTML, JSON, a file — so it is not a typed endpoint and the SDK exposes the address rather than a method. A browser navigation cannot set a header, which is why the key is also accepted in the query string.
//
// Returns a wrapper object for the known response body format(s).
//
// Corresponds with GET /sandbox/{id}/{port}/ (the `ProxyToSandbox` operationId).
func (c *ClientWithResponses) ProxyToSandboxWithResponse(ctx context.Context, id string, port string, reqEditors ...RequestEditorFn) (*ProxyToSandboxResponse, error) {
	rsp, err := c.ProxyToSandbox(ctx, id, port, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseProxyToSandboxResponse(rsp)
}

